  u64 fnv=14695981039346656037ull;for(unsigned i=0;i<128;++i){fnv^=b[i];fnv*=1099511628211ull;}Num(b,96,8,fnv);
  std::copy_n(h.page_type==0x303?"SBPIN001":"SBPINL01",8,b.begin()+128);Num(b,136,2,1);Num(b,138,2,256);Num(b,140,4,384+160*v.records.size());Put(b,144,v.object_uuid);Num(b,160,8,v.epoch);Put(b,168,v.creator_transaction_uuid);Num(b,184,8,v.creator_local_transaction_id);Num(b,192,8,v.flags);Num(b,200,8,v.total_pins);Num(b,208,8,v.first_record);Num(b,216,4,v.records.size());if(v.next)Ref(b,224,*v.next);std::copy(v.next_sha256.begin(),v.next_sha256.end(),b.begin()+272);Num(b,304,8,v.legal_hold_pins);Num(b,312,8,v.lowest_start);Num(b,320,8,v.highest_end);
