  persist(root,a,b);reads=hash_calls=full_calls=0;allocations=0;count_allocations=true;auto result=read(budget);count_allocations=false;const auto nr=reads,nh=hash_calls,nf=full_calls;const auto na=allocations;auto expected_a=a,expected_root=root;expected_a.next_sha256=Hash(Oracle(b));expected_root.next_sha256=Hash(Oracle(expected_a));
  const auto exact=[&](const auto& r){return r.ok()&&r.images.size()==3&&r.retained_image_bytes==budget&&r.images[0].bytes==Oracle(expected_root)&&r.images[1].bytes==Oracle(expected_a)&&r.images[2].bytes==Oracle(b);};Check(exact(result)&&result.images[1].page->records[0].retain_until_unix_ns==1,"actual complete pins including expired but unreleased retention");Empty(read(budget-1));Empty(read(0));
  for(unsigned n=1;n<=nr;++n){reads=0;fail_read=n;result=read(budget);fail_read=0;Empty(result);Check(result.error==E::io_failure,"actual retention read fault");}
  for(unsigned n=1;n<=nh;++n){hash_calls=0;fail_hash=n;result=read(budget);fail_hash=0;Empty(result);Check(result.error==E::hash_failure,"retention multipart provider fault");}
  for(unsigned n=1;n<=nf;++n){full_calls=0;fail_full=n;result=read(budget);fail_full=0;Empty(result);Check(result.error==E::hash_failure,"retention full digest provider fault");}
  if(profile==0){for(unsigned long n=0;n<=na;++n){allocation_budget=n;result=read(budget);allocation_budget=-1;if(result.ok())Check(exact(result),"exact retained images after allocation recovery");else Empty(result);if(n==na)Check(result.ok(),"retention allocation terminal success");}std::cout<<"retention allocation sites="<<na<<" reads="<<nr<<" part hashes="<<nh<<" full hashes="<<nf<<std::endl;}
  for(unsigned n=0;n<12;++n){auto r=root,x=a,y=b;if(n==0)r.legal_hold_pins=0;if(n==1)r.lowest_start=3;if(n==2)r.highest_end=12;if(n==3)y.epoch++;if(n==4)y.creator_transaction_uuid=Id(99);if(n==5)y.creator_local_transaction_id++;if(n==6)y.flags=1;if(n==7)y.records[0].pin_uuid=x.records[0].pin_uuid;if(n==8)y.header.page_uuid=x.header.page_uuid;if(n==9)y.header.page_uuid=z1.page_uuid;if(n==10)y.header.page_generation++;if(n==11)y.first_record=0;persist(r,x,y);result=read(budget);Empty(result);if(n<=2)Check(result.error==E::summary_mismatch,"actual complete pin summaries recomputed");}
